"""Level scripts for TombEngine: a small runtime (zones, item use, enemies, secrets, messages,
teleports, level end) plus per-level data generated from Python.

Lua positions are absolute world units with Y pointing down: (x, -h, z).
"""

RUNTIME = r'''
-- ===================================================================================
-- Coda di Volpe runtime (generated by tools/luagen.py)
-- ===================================================================================
local CDV = {}
local ID = TEN.Objects.ObjID

-- Persistent state lives in LevelVars (saved with the game); always fetched through St().
local function St()
    if LevelVars.CDV == nil then
        LevelVars.CDV = { done = {}, flags = {}, secrets = {} }
    end
    return LevelVars.CDV
end
CDV.St = St

-- Riprese (trailer): Engine\Scripts\CdvRiprese.lua -> return { attivo = true, ciclo = false, solo = nil }
local okRip, RIP = pcall(require, "CdvRiprese")
if not okRip or type(RIP) ~= "table" then RIP = { attivo = false } end
CDV.RIP = RIP
CDV.SHOTS = 0      -- flyby sequences 1..SHOTS placed by tools/shots.py

local msg = nil
local msgTimer = 0

function CDV.Say(text, seconds)
    if RIP.attivo then return end
    if msg ~= nil then
        TEN.Strings.HideString(msg)
    end
    local x, y = TEN.Util.PercentToScreen(50, 84)
    local wx, wy = TEN.Util.PercentToScreen(80, 14)
    msg = TEN.Strings.DisplayString(text, TEN.Vec2(x, y), 0.9, TEN.Color(255, 244, 214), false,
        { TEN.Strings.DisplayStringOption.CENTER, TEN.Strings.DisplayStringOption.SHADOW }, TEN.Vec2(wx, wy))
    TEN.Strings.ShowString(msg, seconds or 6)
end

function CDV.M(name)
    local ok, m = pcall(TEN.Objects.GetMoveableByName, name)
    if ok then return m end
    return nil
end

function CDV.Dead(name)
    local m = CDV.M(name)
    if m == nil then return true end
    if not m:GetValid() then return true end
    return m:GetHP() <= 0
end

function CDV.Active(name)
    local m = CDV.M(name)
    return m ~= nil and m:GetValid() and m:GetActive()
end

-- Floor levers (LEVER_SWITCH) toggle between two states: "pulled" = not in the state it had at start.
function CDV.Pulled(name)
    local m = CDV.M(name)
    if m == nil or not m:GetValid() then return false end
    local k = "s0_" .. name
    local s0 = CDV.Flag(k)
    if s0 == nil then
        s0 = m:GetState()
        CDV.Flag(k, s0)
    end
    return m:GetState() ~= s0
end

function CDV.Enable(name)
    local m = CDV.M(name)
    if m ~= nil and m:GetValid() then m:Enable() end
end

function CDV.Disable(name)
    local m = CDV.M(name)
    if m ~= nil and m:GetValid() then m:Disable() end
end

-- Run fn after a number of frames (30 = 1 s). Not saved: use only for short visual sequences.
local timers = {}
function CDV.After(frames, fn) timers[#timers + 1] = { t = frames, fn = fn } end
local function TimersTick()
    for i = #timers, 1, -1 do
        local t = timers[i]
        t.t = t.t - 1
        if t.t <= 0 then table.remove(timers, i); t.fn() end
    end
end

-- Key into a lock moveable, scripted: Lara steps to the plate, plays the native "use key" animation,
-- then the target (a door) is enabled as if triggered.
function CDV.InsertKey(lockName, targetName, leafName)
    local lock = CDV.M(lockName)
    if lock ~= nil and lock:GetValid() then
        local lp = lock:GetPosition()
        local yaw = lock:GetRotation().y
        local a = math.rad(yaw)
        Lara:SetPosition(TEN.Vec3(lp.x + math.sin(a) * 312, lp.y, lp.z + math.cos(a) * 312), false)
        Lara:SetRotation(TEN.Rotation(0, yaw, 0))
        Lara:SetAnim(131)
        Lara:SetState(42)
    end
    CDV.After(45, function()
        CDV.Enable(targetName)
        if leafName then CDV.Swing(leafName, "y", 90, 40) end
    end)
end

-- Turn a named static about its own origin (hinged leaves and hatches): axis "x", "y" or "z",
-- `by` degrees over `frames` frames.
function CDV.Swing(name, axis, by, frames)
    local ok, st = pcall(TEN.Objects.GetStaticByName, name)
    if not ok or st == nil then return end
    local r0 = st:GetRotation()
    local start = { x = r0.x, y = r0.y, z = r0.z }
    local f = 0
    local function step()
        f = f + 1
        local t = math.min(f / frames, 1.0)
        local r = { x = start.x, y = start.y, z = start.z }
        r[axis] = start[axis] + by * (1 - (1 - t) * (1 - t))
        st:SetRotation(TEN.Rotation(r.x, r.y, r.z))
        if f < frames then CDV.After(1, step) end
    end
    CDV.After(1, step)
end

-- Classic keyhole behaviour without a floor trigger: Lara in front of the lock plate, facing it,
-- presses Action while holding the key -> the inventory opens on that key (using it there runs the
-- CDV.Use entry of the lock). The lock's position is read at run time, so it can be moved in the editor.
function CDV.KeyPrompt(lockName, item, doneId)
    if doneId and CDV.Done(doneId) then return end
    if not CDV.Has(item) then return end
    if not TEN.Input.IsKeyHit(TEN.Input.ActionID.ACTION) then return end
    local lock = CDV.M(lockName)
    if lock == nil or not lock:GetValid() then return end
    local lp, p = lock:GetPosition(), Lara:GetPosition()
    local a = math.rad(lock:GetRotation().y)
    local dx, dz = p.x - lp.x, p.z - lp.z
    local side = dx * math.cos(a) - dz * math.sin(a)
    local ahead = dx * math.sin(a) + dz * math.cos(a)
    local dyaw = math.abs(((Lara:GetRotation().y - lock:GetRotation().y) + 540) % 360 - 180)
    if math.abs(side) < 450 and ahead > -350 and ahead < 520 and math.abs(p.y - lp.y) < 400 and dyaw < 50 then
        TEN.Inventory.SetFocusedItem(item)
    end
end

function CDV.Has(item)
    return TEN.Inventory.GetItemCount(item) > 0
end

function CDV.Give(item, count)
    TEN.Inventory.GiveItem(item, count or 1, true)
end

function CDV.Take(item)
    TEN.Inventory.TakeItem(item, 1)
end

function CDV.Near(x, y, z, r, dy)
    local p = Lara:GetPosition()
    local dx, dz = p.x - x, p.z - z
    if dx * dx + dz * dz > r * r then return false end
    return math.abs(p.y - y) <= (dy or 1536)
end

function CDV.Done(id)
    return St().done[id] == true
end

function CDV.Flag(name, value)
    local S = St()
    if value ~= nil then S.flags[name] = value end
    return S.flags[name]
end

-- Teleport with a short fade (used for building doors that cannot be wall portals).
local tp = nil
function CDV.Teleport(x, y, z, roomName, yaw)
    if tp ~= nil then return end
    tp = { x = x, y = y, z = z, room = roomName, yaw = yaw, t = 0 }
    TEN.View.FadeOut(4)
end

local function TeleportStep()
    if tp == nil then return end
    tp.t = tp.t + 1
    if tp.t == 10 then
        Lara:SetPosition(TEN.Vec3(tp.x, tp.y, tp.z), false)
        local room = TEN.Objects.GetRoomByName(tp.room)
        if room ~= nil then Lara:SetRoomNumber(room:GetRoomNumber()) end
        if tp.yaw ~= nil then Lara:SetRotation(TEN.Rotation(0, tp.yaw, 0)) end
    elseif tp.t >= 12 then
        TEN.View.FadeIn(4)
        tp = nil
    end
end

local zones, uses, drops, secrets, loops = {}, {}, {}, {}, {}

-- zone {id, x, y, z, r, dy, once, need, fn}
function CDV.Zone(z) zones[#zones + 1] = z end
-- use {id, item, x, y, z, r, dy, consume, need, fn, fail}
function CDV.Use(u) uses[#uses + 1] = u end
-- drop {id, enemy, item, text}
function CDV.Drop(d) drops[#drops + 1] = d end
-- secret {index, x, y, z, r}
function CDV.Secret(s) secrets[#secrets + 1] = s end
-- loop function called every frame
function CDV.Loop(f) loops[#loops + 1] = f end

-- Full-screen video from Engine\FMV (mp4/mkv/mov/avi). A missing file only writes a warning in the log.
function CDV.Video(name)
    if RIP.attivo then return end
    TEN.View.PlayVideo(name)
end

local rip = { t = 0, cur = 0, wait = 60 }
local function RipreseTick()
    if not RIP.attivo or CDV.SHOTS == 0 then return end
    if TEN.View.GetCameraType() == TEN.View.CameraType.FLYBY then
        rip.wait = 45
        return
    end
    if rip.wait > 0 then
        rip.wait = rip.wait - 1
        return
    end
    local first = RIP.solo or 1
    local last = RIP.solo or CDV.SHOTS
    if rip.cur == 0 then
        rip.cur = first
    else
        rip.cur = rip.cur + 1
        if rip.cur > last then
            if not RIP.ciclo then
                rip.cur = last + 1
                rip.wait = 1e9
                return
            end
            rip.cur = first
        end
    end
    TEN.View.PlayFlyby(rip.cur)
end
CDV.RipreseTick = RipreseTick

function CDV.Tick()
    local S = St()
    TimersTick()
    RipreseTick()
    TeleportStep()
    for _, z in ipairs(zones) do
        if not (z.once and S.done[z.id]) then
            if (z.need == nil or z.need()) and CDV.Near(z.x, z.y, z.z, z.r, z.dy) then
                if z.once then S.done[z.id] = true end
                if z.text then CDV.Say(z.text, z.secs) end
                if z.fn then z.fn() end
            end
        end
    end
    for _, d in ipairs(drops) do
        if not S.done["drop_" .. d.id] and CDV.Dead(d.enemy) then
            S.done["drop_" .. d.id] = true
            CDV.Give(d.item, 1)
            if d.text then CDV.Say(d.text, 6) end
        end
    end
    for _, s in ipairs(secrets) do
        if not S.secrets["s" .. s.index] and CDV.Near(s.x, s.y, s.z, s.r, 1024) then
            S.secrets["s" .. s.index] = true
            TEN.Flow.AddSecret(s.index)
            CDV.Say(s.text or "Hai trovato una Stella dei Dioscuri!", 5)
            if s.give then CDV.Give(s.give, 1) end
        end
    end
    for _, f in ipairs(loops) do f() end
end

function CDV.UseItem()
    local S = St()
    local item = TEN.Inventory.GetUsedItem()
    for _, u in ipairs(uses) do
        local ux, uy, uz = u.x, u.y, u.z
        if u.near then
            local m = CDV.M(u.near)
            if m ~= nil and m:GetValid() then local q = m:GetPosition(); ux, uy, uz = q.x, q.y, q.z end
        end
        if item == u.item and not S.done["use_" .. u.id] and CDV.Near(ux, uy, uz, u.r, u.dy) then
            if u.need == nil or u.need() then
                TEN.Inventory.ClearUsedItem()
                S.done["use_" .. u.id] = true
                if u.consume then CDV.Take(u.item) end
                if u.text then CDV.Say(u.text, u.secs or 7) end
                if u.fn then u.fn() end
                return
            elseif u.fail then
                TEN.Inventory.ClearUsedItem()
                CDV.Say(u.fail, 6)
                return
            end
        end
    end
end

function CDV.End(levelIndex, startPos)
    TEN.Flow.EndLevel(levelIndex, startPos)
end
'''

FOOTER = r'''
if CDV_TEST ~= nil then CDV_TEST(CDV, zones, uses) end

-- Playtest hook: Engine\Scripts\CdvTest.lua -> return { Oliveri = { tp = {x, y, z, "ROOM", yaw}, give = {"KEY_ITEM1"} } }
local okT, TST = pcall(require, "CdvTest")
if not okT or type(TST) ~= "table" then TST = {} end
local function TestStart()
    local t = TST[CDV.KEY or ""]
    if t == nil then return end
    if t.tp then
        Lara:SetPosition(TEN.Vec3(t.tp[1], t.tp[2], t.tp[3]), false)
        local room = TEN.Objects.GetRoomByName(t.tp[4])
        if room ~= nil then Lara:SetRoomNumber(room:GetRoomNumber()) end
        if t.tp[5] then Lara:SetRotation(TEN.Rotation(0, t.tp[5], 0)) end
    end
    for _, name in ipairs(t.kill or {}) do
        local m = CDV.M(name)
        if m ~= nil and m:GetValid() then m:SetHP(0) end
    end
end

LevelFuncs.OnStart = function()
    if CDV.VIDEO then CDV.Video(CDV.VIDEO) end
    if CDV.Start then CDV.Start() end
    TestStart()
end
LevelFuncs.OnLoad = function() end
LevelFuncs.OnSave = function() end
local hudStr = nil
local testFrame = 0
local testInfo = ""
local function TestHud()
    local t = TST[CDV.KEY or ""]
    if t == nil then return end
    testFrame = testFrame + 1
    if testFrame == 10 then
        for _, name in ipairs(t.give or {}) do
            local id = TEN.Objects.ObjID[name]
            if id ~= nil then TEN.Inventory.GiveItem(id, 1, false); testInfo = testInfo .. " +" .. name
            else testInfo = testInfo .. " ?" .. name end
        end
    end
    if not t.hud then return end
    local p = Lara:GetPosition()
    local r = Lara:GetRotation()
    local txt = string.format("x %d  y %d  z %d  yaw %d  room %d  sx %d sz %d%s", p.x, p.y, p.z, math.floor(r.y), Lara:GetRoomNumber(), math.floor(p.x / 1024), math.floor(p.z / 1024), testInfo)
    if t.watch then
        local m = CDV.M(t.watch)
        if m ~= nil and m:GetValid() then
            local q = m:GetPosition()
            local a = math.rad(m:GetRotation().y)
            local dx, dz = p.x - q.x, p.z - q.z
            local rx = dx * math.cos(a) - dz * math.sin(a)
            local rz = dx * math.sin(a) + dz * math.cos(a)
            txt = txt .. string.format("\n%s rel x %d y %d z %d  rot %d", t.watch, math.floor(rx), p.y - q.y, math.floor(rz), math.floor(m:GetRotation().y))
        end
    end
    if hudStr == nil then
        local x, y = TEN.Util.PercentToScreen(2, 4)
        hudStr = TEN.Strings.DisplayString(txt, TEN.Vec2(x, y), 0.7, TEN.Color(255, 255, 0), false, {})
    else
        hudStr:SetKey(txt)
    end
    TEN.Strings.ShowString(hudStr, 1)
end
LevelFuncs.OnLoop = function()
    CDV.Tick()
    TestHud()
end
LevelFuncs.OnUseItem = function()
    CDV.UseItem()
end
LevelFuncs.OnEnd = function() end
'''


def num(v):
    return ("%d" % v) if float(v).is_integer() else ("%.1f" % v)


def pos(p):
    """p = (x, -h, z) tuple in Lua coordinates."""
    return "x = %s, y = %s, z = %s" % (num(p[0]), num(p[1]), num(p[2]))


def lua_str(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n") + '"'


class LuaLevel:
    def __init__(self, title, key):
        self.title = title
        self.key = key
        self.parts = []
        self.video = None      # FMV played when the level starts (not on savegame load)
        self.shots = 0         # flyby sequences for the riprese mode

    def add(self, code):
        self.parts.append(code.strip("\n"))

    def zone(self, zid, p, r=1024, dy=1536, once=True, text=None, secs=6, fn=None, need=None):
        items = ["id = %s" % lua_str(zid), pos(p), "r = %d" % r, "dy = %d" % dy, "once = %s" % ("true" if once else "false")]
        if text:
            items.append("text = %s, secs = %d" % (lua_str(text), secs))
        if need:
            items.append("need = function() return %s end" % need)
        if fn:
            items.append("fn = function()\n        %s\n    end" % fn.strip().replace("\n", "\n        "))
        self.add("CDV.Zone({ %s })" % ", ".join(items))

    def use(self, uid, item, p, r=1536, dy=1536, consume=True, text=None, fn=None, need=None, fail=None, near=None):
        items = ["id = %s" % lua_str(uid), "item = %s" % item, pos(p), "r = %d" % r, "dy = %d" % dy,
                 "consume = %s" % ("true" if consume else "false")]
        if near:
            items.append("near = %s" % lua_str(near))
        if text:
            items.append("text = %s" % lua_str(text))
        if need:
            items.append("need = function() return %s end" % need)
        if fail:
            items.append("fail = %s" % lua_str(fail))
        if fn:
            items.append("fn = function()\n        %s\n    end" % fn.strip().replace("\n", "\n        "))
        self.add("CDV.Use({ %s })" % ", ".join(items))

    def drop(self, did, enemy, item, text):
        self.add("CDV.Drop({ id = %s, enemy = %s, item = %s, text = %s })" % (
            lua_str(did), lua_str(enemy), item, lua_str(text)))

    def secret(self, index, p, r=900, give=None, text=None):
        items = ["index = %d" % index, pos(p), "r = %d" % r]
        if give:
            items.append("give = %s" % give)
        if text:
            items.append("text = %s" % lua_str(text))
        self.add("CDV.Secret({ %s })" % ", ".join(items))

    def start(self, code):
        self.add("CDV.Start = function()\n    %s\nend" % code.strip().replace("\n", "\n    "))

    def loop(self, code):
        self.add("CDV.Loop(function()\n    %s\nend)" % code.strip().replace("\n", "\n    "))

    def text(self):
        head = "-- Coda di Volpe - %s (TombEngine level script)\n" % self.title
        head += "-- Va in C:\\CodaDiVolpe\\Engine\\Scripts\\Levels\\%s.lua (generato da tools/episode.py)\n" % self.key
        data = ["CDV.KEY = %s" % lua_str(self.key)]
        if self.video:
            data.append("CDV.VIDEO = %s" % lua_str(self.video))
        if self.shots:
            data.append("CDV.SHOTS = %d" % self.shots)
        return head + RUNTIME + "\n-- ----------------------------------------------------------------- level data\n\n" + \
            "\n\n".join((["\n".join(data)] if data else []) + self.parts) + "\n" + FOOTER
